import{_ as a,H as l,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const E=JSON.parse('{"title":"26 | 从大厂到创业公司，管理上需要怎样转变？","description":"","frontmatter":{},"headers":[{"level":2,"title":"创业公司与大厂的差异","slug":"创业公司与大厂的差异","link":"#创业公司与大厂的差异","children":[]},{"level":2,"title":"应对策略","slug":"应对策略","link":"#应对策略","children":[{"level":3,"title":"研发分层","slug":"研发分层","link":"#研发分层","children":[]},{"level":3,"title":"鼓励员工做全栈","slug":"鼓励员工做全栈","link":"#鼓励员工做全栈","children":[]},{"level":3,"title":"管理者如何鼓励员工做全栈","slug":"管理者如何鼓励员工做全栈","link":"#管理者如何鼓励员工做全栈","children":[]},{"level":3,"title":"重视 POC 的反馈","slug":"重视-poc-的反馈","link":"#重视-poc-的反馈","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"技术领导力实战笔记2022/26｜从大厂到创业公司，管理上需要怎样转变？.md","filePath":"技术领导力实战笔记2022/26｜从大厂到创业公司，管理上需要怎样转变？.md","lastUpdated":1795558086000}'),p={name:"技术领导力实战笔记2022/26｜从大厂到创业公司，管理上需要怎样转变？.md"};function n(r,e,o,s,h,c){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_26-从大厂到创业公司-管理上需要怎样转变" tabindex="-1">26 | 从大厂到创业公司，管理上需要怎样转变？ <a class="header-anchor" href="#_26-从大厂到创业公司-管理上需要怎样转变" aria-label="Permalink to &quot;26 | 从大厂到创业公司，管理上需要怎样转变？&quot;">​</a></h1><p>你好，我是舒超。</p><p>我职业生涯过去十年的上半段在腾讯负责微博微群、消息流广告、视频评论等社交型的业务系统，下半段在美团基础架构负责云原生基础设施的演进工作，现在星汉未来担任 CTO，负责公司产研推进工作。加入星汉未来的时间点很好记，是 2021 年 12 月 31 日。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/26/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/26/1.png" alt=""></a></p><p>可以说这个时间是我从大厂到创业公司的一个交界点，在真正接手星汉未来的工作之后，我发现大厂与创业公司在技术管理方面的差异很大。所以今天我就来分享一下从大厂到创业团队技术管理上面临的变化及应对策略。</p><h2 id="创业公司与大厂的差异" tabindex="-1">创业公司与大厂的差异 <a class="header-anchor" href="#创业公司与大厂的差异" aria-label="Permalink to &quot;创业公司与大厂的差异&quot;">​</a></h2><p>星汉未来是一家创业公司，80% 以上的员工原来都是字节、快手、微博等互联网大厂基础架构部门的研发，大家从大公司到小公司，在认知以及做事方式上会带有大公司的影子。比如：</p><ol><li><p>对项目计划的稳定性有较高的预期，预定的交付内容和交付时间被打乱会明显影响状态及情绪。</p></li><li><p>做事有较强的边界和范围意识，负责 A 模块的天然不关心 B 模块的问题。</p></li><li><p>对流程制度有较深的依赖，希望在各个环节都有相应的规范和责任人，出了问题就想要一套制度来填充。</p></li></ol><p>我们都知道，以上这些研发人员的特征，是大厂在业务稳定、人员众多、部门完备的背景下，规范企业运作的管理方式下形成的。我之前工作过的美团和腾讯，也沉淀下来了很多管理理念、管理方法以及流程制度。</p><p>而创业公司，这些前提都不具备。比如：</p><ol><li><p>一开始目标客户或市场需求都是未经验证甚至模糊的，这必然带来项目计划和交付日期的频繁迭代。</p></li><li><p>人力肯定是缺乏的，经常是一个人当一个半甚至两个人用，今天做 A 模块明天做 B 模块，所以模块或组件是谁的很难区分。</p></li><li><p>整个公司主要人员角色的划分可能除了产品，研发等大类，连前端，QA 这些环节都是缺失或兼任的，所以有可能大厂的一个基本制度流程，在创业公司实际也就是经手 1～2 个人，几句话的事情，而且很可能明天又有新的变化，所以也没有必要为此建立制度。</p></li></ol><h2 id="应对策略" tabindex="-1">应对策略 <a class="header-anchor" href="#应对策略" aria-label="Permalink to &quot;应对策略&quot;">​</a></h2><p>总体来说，变化多、节奏快、资源紧是创业公司的常态，而我们的管理办法也必须基于这三个核心事实进行，如何让处在创业时期的公司“小步快跑”是管理者的重任。下面我来分享下，我加入星汉之后在管理上的一些策略。</p><h3 id="研发分层" tabindex="-1">研发分层 <a class="header-anchor" href="#研发分层" aria-label="Permalink to &quot;研发分层&quot;">​</a></h3><p>首先，创业公司的研发虽然人数有限，但也要分层管理。从招聘的时候就要有意识地进行区分，目前星汉这边的研发主要分为三层：</p><ol><li><p>一线研发：技术能力强但资历较浅，喜欢钻研技术的同学</p></li><li><p>架构师：兼具代码及架构设计能力，有一定业界视野</p></li><li><p>技术 Leader：有能力、有眼界，懂团队管理。</p></li></ol><p>那么在创业公司，对这三个层级的员工要提出什么样的要求呢？</p><p>一线研发最重要的就是执行力，将落地执行的效率、质量做到极致，成为公司战略的第一线抓手。</p><p>架构师团队的主要职责是不让客户突如其来的需求直接震荡到研发，架构师先做缓冲去探寻可行性，大概的技术方案搞清楚之后，再切分成较细的模块或者动作传递给一线研发。所以整个震荡的节奏、频次、复杂度都被架构师这个缓冲层消化掉了。</p><p>创业团队的技术 Leader，除去必备的技术能力与管理能力不谈，不管是传递公司的决定，还是传递客户的需求，一定要和团队同步清楚具体的原因和要求，做到信息透明，同时尽量给员工手上工作的收尾和切换留出合理时间。</p><h3 id="鼓励员工做全栈" tabindex="-1">鼓励员工做全栈 <a class="header-anchor" href="#鼓励员工做全栈" aria-label="Permalink to &quot;鼓励员工做全栈&quot;">​</a></h3><p>创业公司职能虽有基础的职能划分，比如产品、研发、市场、社区等，但是在实际过程工作中，需要快速出成果，快速试错，基于这个目标，可能研发直接就做了产品的事情，或者市场做了社区的事情。</p><p>这在创业团队属于非常正常的操作，因为人手确实有限。解决这个问题有两种方案，一是扩充人手，二是拓展员工的能力。但因为资金问题方案一往往很难实现，这时候在管理上，可以往拓展员工能力方面努力，鼓励员工们做全栈。</p><p>比如，项目负责人在客户环境验证一个压测功能的时候，发现了产品没有考虑到的情况，就直接换了压测算法。再比如市场人员在攻克客户订单的时候，发现某个功能点确实有一些价值，但是客户付费意愿不强，就放到社区去开源当甜点引流到商业产品。这些行为都超越了他们本身的职能范围，但都对公司的成长有利，是值得被肯定的。创业公司的员工如果自驱力够强，其实是可以涉猎很多领域的，对个人成长也很有帮助。</p><p>因此，我非常鼓励前端、后端、QA、甚至包括架构师，在做好自己本职工作的同时，勇于突破自己的一亩三分地，去其他地盘“指手画脚”。比如前端帮 QA 调研自动化测试框架，解决产研交付 QA 卡点阻塞的问题；后端在前端紧缺时，也会承担起前端工作，全栈研发。这样即使人力有限，也能很好地完成任务，同时也能最大限度地发挥人员的价值。</p><h3 id="管理者如何鼓励员工做全栈" tabindex="-1">管理者如何鼓励员工做全栈 <a class="header-anchor" href="#管理者如何鼓励员工做全栈" aria-label="Permalink to &quot;管理者如何鼓励员工做全栈&quot;">​</a></h3><p>首先，我们需要在团队内部倡导这种精神，鼓励员工跨越领域，横向拓展自己的能力，给研发线上的每一个人种下全栈全流程我随时有可能要顶上去的意识。</p><p>在分配任务时，允许一部分边界模糊的任务存在，给员工尝试的机会，让他们主动去探索。同时，身为管理者我们也要负起责任，对人员“错位”可能导致的项目风险也要有清醒的认识和PlanB。</p><p>最后，在有条件的情况下，我们也可以在团队内部安排轮岗，尤其是对一些有意愿且有能力的技术骨干，通过轮岗制度让他们多掌握一门技术，涉猎其他领域，对企业人才培养和员工的个人成长是非常有必要的。</p><h3 id="重视-poc-的反馈" tabindex="-1">重视 POC 的反馈 <a class="header-anchor" href="#重视-poc-的反馈" aria-label="Permalink to &quot;重视 POC 的反馈&quot;">​</a></h3><p>创业公司的产品在与市场达到最佳的契合点（PMF）之前基本不能认为是成熟（其实之后也不一定算）。所以哪怕前期经过了详尽的市场调研，或者原型思路经过大厂生产环境验证，后面到客户现场也难免出现不匹配、不兼容以及没考虑到的各种问题。</p><p>这个是很正常的，并非某一个特定环节的责任。这时客户现场的项目负责人（POC）其实就是“能听得见炮火的人”，他们直接面对客户或好或坏的反馈。同时他们又是非常了解产品的人，所以他们的意见是很重要的，对他们意见的重视程度及响应速度，直接决定了这个客户是否能被拿下，以及拿下这个客户的速度，甚至客单价的高低。理想的 POC 人员配置，是产品 + 研发 + 销售组成的“铁三角”。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/26/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%8A%80%E6%9C%AF%E9%A2%86%E5%AF%BC%E5%8A%9B%E5%AE%9E%E6%88%98%E7%AC%94%E8%AE%B02022/images/26/2.png" alt=""></a></p><p>星汉因为前期人力紧缺，POC 暂时是研发线人员代理。但由于研发和 POC 的节奏和日常任务有显著差异，所以我们从组织建设上，划分为常规产研和 POC 驻场交付两条线。</p><p>POC 线反馈的 Bug 及需求，优先级会远高于产研线的非客户需求。和产品落地相关的定制化需求，先由 POC 线现场承接研发，具备规模化价值的需求才交给产研线。而产研线的一些初步方案及 demo，也会交给 POC 线呈现给客户做快速试探与反馈。两边协同联动，敏捷配合，逐步将设想中的产品形态向现实的商业交付物方向引导，为公司创造价值。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>总的来说，创业公司和大厂在管理方法上有一些明显的差异，创业公司的普遍状态是变化多、节奏快、资源紧，我们需要根据这些特点，调整管理战略。</p><ol><li><p>研发需分层管理：一线研发重执行力和代码能力，架构师需兼顾代码能力和架构设计能力，技术管理者要做到信息透明化，减少信息差。</p></li><li><p>在人力紧缺的情况下，鼓励员工拓展自身能力，成为全栈工程师。</p></li><li><p>重视 POC 的反馈，重视客户的需求。</p></li></ol><p>这些就是我从大厂到创业公司之后感受到的差异及我的管理策略，希望能给你带来一些帮助。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>其实关于全栈工程师，争议还是挺多的，有的人觉得成为全栈工程师是很难做到的，还很有可能导致一桶水不满，半桶水晃荡，还有人觉得全栈工程师应该大力提倡，我们的社会缺少这样的人才。你是怎么看要不要成为全栈工程师这件事情的呢？欢迎在评论区留下你的思考和见解，也欢迎你把这节课分享给需要的朋友。</p>',41)])])}const _=a(p,[["render",n]]);export{E as __pageData,_ as default};
